//! Zed's tasks for a Kargo project: `.zed/tasks.json`, written by `kargo ide --zed`.
//!
//! Zed runs a task when you click the run button its Kotlin extension shows next to `fun main`
//! and test functions, picking the tasks whose tags match the button's (`kotlin-main`,
//! `kotlin-test`, ...). Kargo writes tasks with those tags that run `kargo run` and `kargo test`,
//! the project's [runnables](crate::project::runnables) and everyday commands. Like the other
//! generated files, the file is only replaced while it still holds what Kargo last wrote, and
//! it is written again when `kargo.toml` or `kargo.lock` change.

use std::path::{Path, PathBuf};

use anyhow::Result;
use serde_json::{Value, json};

use kargo_util::config::Config;

use crate::project::{self, Written};

/// Written at the top of the generated file.
const HEADER: &str = "// Generated by `kargo ide --zed`; it is replaced when kargo.toml or kargo.lock change.\n// Delete this file, or edit it to stop Kargo from replacing it.\n";

/// The `.zed/tasks.json` of the project described by `metadata`.
pub fn tasks(metadata: &Value) -> Value {
    let root = PathBuf::from(metadata["root"].as_str().unwrap_or_default());
    let workspace = metadata["members"].as_array().is_some_and(|m| m.len() > 1);
    let mut tasks = Vec::new();
    let task = |label: String, args: Vec<String>, cwd: &str, tags: &[&str]| {
        let mut task = json!({
            "label": label,
            "command": "kargo",
            "args": args,
            "cwd": cwd,
            "use_new_terminal": false,
            "allow_concurrent_runs": false,
            "reveal": "always",
        });
        if !tags.is_empty() {
            task["tags"] = json!(tags);
        }
        task
    };
    let words = |parts: &[&str]| parts.iter().map(|s| (*s).to_owned()).collect::<Vec<String>>();
    const ROOT: &str = "$ZED_WORKTREE_ROOT";
    // The package of the open file: Kargo finds the nearest kargo.toml from its directory.
    const HERE: &str = "$ZED_DIRNAME";

    // Run buttons of the Kotlin extension.
    let class = "$ZED_CUSTOM_kotlin_package_name.$ZED_CUSTOM_kotlin_class_name";
    let nested = "$ZED_CUSTOM_kotlin_package_name.$ZED_CUSTOM_kotlin_outer_class_name.$ZED_CUSTOM_kotlin_class_name";
    let method = "$ZED_CUSTOM_kotlin_method_name";
    for (filter, tag) in [
        (format!("{class}.{method}"), "kotlin-test"),
        (class.to_owned(), "kotlin-test-class"),
        (format!("{nested}.{method}"), "kotlin-test-nested"),
        (nested.to_owned(), "kotlin-test-class-nested"),
    ] {
        tasks.push(task(format!("kargo test {filter}"), vec!["test".to_owned(), filter], HERE, &[tag]));
    }

    let packages: Vec<&Value> = metadata["packages"].as_array().into_iter().flatten().filter(|p| p["member"] == true).collect();
    for runnable in project::runnables(metadata, "kargo", None) {
        let args: Vec<String> = runnable["args"].as_array().into_iter().flatten().filter_map(Value::as_str).map(str::to_owned).collect();
        let package = runnable["package"].as_str().unwrap_or_default();
        let cwd = packages
            .iter()
            .find(|p| p["name"] == package)
            .and_then(|p| p["root"].as_str())
            .map(|dir| relative(&root, Path::new(dir)))
            .unwrap_or_else(|| ROOT.to_owned());
        let mut label = format!("kargo {}", args.join(" "));
        if workspace {
            label.push_str(&format!(" ({package})"));
        }
        let tags: &[&str] = if runnable["kind"] == "run" { &["kotlin-main"] } else { &[] };
        tasks.push(task(label, args, &cwd, tags));
    }

    for (args, cwd) in [
        (&["build"][..], ROOT),
        (&["build", "--release"][..], ROOT),
        (&["check", "--tests"][..], ROOT),
        (&["run", "--hot-reload"][..], HERE),
        (&["test"][..], ROOT),
        (&["test"][..], HERE),
        (&["clean"][..], ROOT),
        (&["fetch", "--sources"][..], ROOT),
        (&["update"][..], ROOT),
        (&["outdated"][..], ROOT),
        (&["add", "$ZED_SELECTED_TEXT"][..], HERE),
        (&["remove", "$ZED_SELECTED_TEXT"][..], HERE),
    ] {
        let mut label = format!("kargo {}", args.join(" "));
        if cwd == HERE && (args == ["test"] || args == ["run", "--hot-reload"]) {
            label.push_str(" (this package)");
        }
        tasks.push(task(label, words(args), cwd, &[]));
    }
    Value::Array(tasks)
}

/// `dir` as a path below `$ZED_WORKTREE_ROOT`, with `/` separators so the file is the same on
/// every OS.
fn relative(root: &Path, dir: &Path) -> String {
    match dir.strip_prefix(root) {
        Ok(rel) if rel.as_os_str().is_empty() => "$ZED_WORKTREE_ROOT".to_owned(),
        Ok(rel) => {
            let parts: Vec<String> = rel.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect();
            format!("$ZED_WORKTREE_ROOT/{}", parts.join("/"))
        }
        Err(_) => dir.display().to_string(),
    }
}

/// Writes `.zed/tasks.json` for the project described by `metadata`, unless someone else wrote
/// the file there now, and records the project's fingerprint so later commands keep it current.
pub fn write(metadata: &Value) -> Result<Written> {
    let root = PathBuf::from(metadata["root"].as_str().unwrap_or_default());
    let state = project::state_dir(metadata);
    let text = format!("{HEADER}{}\n", serde_json::to_string_pretty(&tasks(metadata))?);
    let mut written = Written::default();
    project::generate(&root.join(".zed").join("tasks.json"), &text, &state, &mut written)?;
    if written.foreign.is_empty()
        && let Ok(fingerprint) = project::fingerprint(&root)
    {
        kargo_util::fs::write_string_atomic(&state.join("zed-fingerprint"), &fingerprint)?;
    }
    Ok(written)
}

/// Writes `.zed/tasks.json` again if Kargo wrote it before and `kargo.toml` or `kargo.lock`
/// changed since. Returns `None` when there is nothing to do.
pub fn refresh(config: &Config, root: &Path) -> Option<Result<Written>> {
    let project = kargo_ops::workspace::Project::discover(root, None).ok()?;
    let record = std::fs::read_to_string(project.target_dir().join("lsp").join("zed-fingerprint")).ok()?;
    if record.trim() == kargo_ops::ops::metadata::fingerprint(&project) {
        return None;
    }
    Some(project::metadata(config, project.root(), true).and_then(|m| write(&m)))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Value {
        json!({
            "root": "/p",
            "target-dir": "/p/target",
            "members": ["app"],
            "packages": [{
                "name": "app",
                "member": true,
                "root": "/p",
                "bins": [{ "name": "tool", "main": "a.ToolKt" }],
                "tasks": [{ "name": "hello" }],
                "targets": [{ "kind": "jvm", "main-class": "a.MainKt" }, { "kind": "wasm", "wasm-kind": "library" }]
            }]
        })
    }

    fn labels_tagged<'a>(tasks: &'a Value, tag: &str) -> Vec<&'a str> {
        tasks
            .as_array()
            .unwrap()
            .iter()
            .filter(|t| t["tags"].as_array().is_some_and(|tags| tags.iter().any(|x| x == tag)))
            .map(|t| t["label"].as_str().unwrap())
            .collect()
    }

    #[test]
    fn binds_kargo_to_the_run_buttons_of_the_kotlin_extension() {
        let tasks = tasks(&sample());
        assert_eq!(labels_tagged(&tasks, "kotlin-main"), ["kargo run -t jvm", "kargo run --bin tool"]);
        let test = &tasks.as_array().unwrap()[0];
        assert_eq!(test["tags"], json!(["kotlin-test"]));
        assert_eq!(
            test["args"],
            json!(["test", "$ZED_CUSTOM_kotlin_package_name.$ZED_CUSTOM_kotlin_class_name.$ZED_CUSTOM_kotlin_method_name"])
        );
        assert_eq!(test["cwd"], "$ZED_DIRNAME");
        assert_eq!(labels_tagged(&tasks, "kotlin-test-class-nested").len(), 1);
        let all: Vec<&str> = tasks.as_array().unwrap().iter().map(|t| t["label"].as_str().unwrap()).collect();
        for label in [
            "kargo test -t wasm",
            "kargo task hello",
            "kargo build",
            "kargo run --hot-reload (this package)",
            "kargo fetch --sources",
            "kargo add $ZED_SELECTED_TEXT",
        ] {
            assert!(all.contains(&label), "{label} in {all:?}");
        }
    }

    #[test]
    fn runs_workspace_members_in_their_directory() {
        let mut metadata = sample();
        metadata["members"] = json!(["app", "lib"]);
        metadata["packages"][0]["root"] = json!(Path::new("/p").join("apps").join("app").display().to_string());
        let tasks = tasks(&metadata);
        let run = tasks.as_array().unwrap().iter().find(|t| t["label"] == "kargo run -t jvm (app)").unwrap();
        assert_eq!(run["cwd"], "$ZED_WORKTREE_ROOT/apps/app");
    }

    #[test]
    fn writes_the_file_only_while_kargo_owns_it() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        let mut metadata = sample();
        metadata["root"] = json!(root.display().to_string());
        metadata["target-dir"] = json!(root.join("target").display().to_string());
        let file = root.join(".zed").join("tasks.json");
        assert_eq!(write(&metadata).unwrap().changed, std::slice::from_ref(&file));
        let text = std::fs::read_to_string(&file).unwrap();
        assert!(text.starts_with("// Generated by `kargo ide --zed`"));
        assert!(write(&metadata).unwrap().changed.is_empty());
        std::fs::write(&file, "[]").unwrap();
        assert_eq!(write(&metadata).unwrap().foreign, [file]);
    }
}
